SINA_SMART["infect-hiv-manifestations"] = {"lecture":"infect-hiv-manifestations","title":"Other clinical manifestations of AIDS","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"infect-hiv-manifestations:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"infect-hiv-manifestations:e0","text":"Oesophageal candidiasis: dysphagia, retrosternal pain, white coating → endoscopy, fluconazole, HIV test.","topic":"Candidiasis","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-hiv-manifestations:e1","text":"TB: commonest OI, all CD4 levels, ~1/3 of HIV deaths.","topic":"Tuberculosis","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-hiv-manifestations:e2","text":"HIV ↑ TB risk (↓ Th1, IFN-γ); TB ↑ HIV replication (TNF, IL-1, IL-6).","topic":"Tuberculosis","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-hiv-manifestations:e3","text":"Every TB → HIV test; every HIV → TB assessment.","topic":"Tuberculosis","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-hiv-manifestations:e4","text":"CMV: CD4 < 50; retinitis → blindness.","topic":"CMV and cryptosporidiosis","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-hiv-manifestations:e5","text":"Cryptosporidiosis: chronic diarrhoea, sclerosing cholangitis.","topic":"CMV and cryptosporidiosis","sec":3,"importance":"core","highYield":"untested"},{"id":"infect-hiv-manifestations:e6","text":"Kaposi = HHV-8; lymphoma = EBV; cervical cancer = HPV.","topic":"Cancers","sec":4,"importance":"core","highYield":"untested"},{"id":"infect-hiv-manifestations:e7","text":"Kaposi lesions: purple-brown macules and nodules; biopsy.","topic":"Cancers","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"n9j324":"a","khhzwi":"a","1xfdrv4":"a","syxgu4":"a","1alnc7w":"a","yip34l":"a","1x785zw":"a","og3h6":"a","b2gfvt":"a","9k8s1z":"a","104i3i1":"a","1v35rki":"a"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"infect-hiv-manifestations:s0":{"s":0,"u":["Beyond Pneumocystis and toxoplasmosis, AIDS brings a set of infections and cancers that should each prompt HIV screening : oro-oesophageal candidiasis, tuberculosis, CMV infection, cryptosporidiosis, Kaposi sarcoma and lymphomas ."],"dp":[]},"infect-hiv-manifestations:e0":{"s":1,"u":["Oesophageal candidiasis: dysphagia, retrosternal pain, white coating → endoscopy, fluconazole, HIV test.","Bucco-oesophageal candidiasis in a person living with HIV: dysphagia, retrosternal pain and a whitish oropharyngeal coating .","Confirm with upper GI endoscopy ; treat with fluconazole ; screen for HIV."],"dp":[]},"infect-hiv-manifestations:e1":{"s":2,"u":["TB: commonest OI, all CD4 levels, ~1/3 of HIV deaths.","The most frequent opportunistic infection in AIDS, at all stages of immunodepression, responsible for about one third of HIV deaths ."],"dp":[]},"infect-hiv-manifestations:e2":{"s":2,"u":["HIV ↑ TB risk (↓ Th1, IFN-γ); TB ↑ HIV replication (TNF, IL-1, IL-6).","HIV raises TB risk (loss of Th1 cells, less interferon-γ); TB accelerates HIV (macrophages make TNF, IL-1 and IL-6, increasing replication)."],"dp":[{"h":"Why TB and HIV make each other worse","t":"Controlling TB depends on Th1 cells that release interferon-γ to activate macrophages; HIV destroys exactly those cells, so latent TB reactivates. In turn, the inflammation of active TB floods tissues with TNF and interleukins that switch on HIV replication in infected cells. Each disease speeds the other, which is why they are always screened for together. Source: the lecture's tuberculosis slides."}]},"infect-hiv-manifestations:e3":{"s":2,"u":["Every TB → HIV test; every HIV → TB assessment.","Rule: every TB patient is screened for HIV, and every HIV patient is assessed for TB .","HIV raises TB risk (loss of Th1 cells, less interferon-γ); TB accelerates HIV (macrophages make TNF, IL-1 and IL-6, increasing replication)."],"dp":[]},"infect-hiv-manifestations:e4":{"s":3,"u":["CMV: CD4 < 50; retinitis → blindness.","CMV appears at CD4 under 50/mm³ .","Retinitis is the main site: visual problems, fundus with exudates and haemorrhagic necrosis , risk of blindness ."],"dp":[]},"infect-hiv-manifestations:e5":{"s":3,"u":["Cryptosporidiosis: chronic diarrhoea, sclerosing cholangitis.","Chronic diarrhoea in AIDS: cryptosporidiosis, isosporiasis.","Cryptosporidiosis : intestinal (acute or chronic diarrhoea, abdominal pain) or biliary ( sclerosing cholangitis , pain, vomiting); diagnosed by stool parasitology, colonoscopic biopsy and abdominal ultrasound."],"dp":[]},"infect-hiv-manifestations:e6":{"s":4,"u":["Kaposi = HHV-8; lymphoma = EBV; cervical cancer = HPV.","HIV does not directly cause cancer but promotes it through immunosuppression; the cancers are due to other viruses: HHV-8 → Kaposi sarcoma , EBV → non-Hodgkin lymphoma , HPV → cervical cancer .","Lymphomas are staged with CT and MRI."],"dp":[{"h":"Why these cancers are called AIDS-defining","t":"Kaposi sarcoma, EBV lymphomas and HPV cervical cancer are caused by viruses the immune system normally keeps in check. When HIV removes that surveillance, the viruses drive malignant growth. Finding one of these cancers therefore suggests severe immunosuppression and should always trigger an HIV test. Source: the lecture's cancers slide."}]},"infect-hiv-manifestations:e7":{"s":4,"u":["Kaposi lesions: purple-brown macules and nodules; biopsy.","Kaposi sarcoma : skin, mucosal and/or visceral; lesions are purple-brown macules , pigmented papulo-nodules, angiomatoid nodules, infiltrated, verrucous or ulcerated plaques; limb lymphoedema can reveal it; many lesions, mucosal and facial locations are suggestive; biopsy confirms."],"dp":[]}},"meta":{"n9j324":{"a":"recall","vg":"infect-hiv-manifestations:e0/recall/1"},"khhzwi":{"a":"recall","vg":"infect-hiv-manifestations:e0/recall/2"},"1xfdrv4":{"a":"recall","vg":"infect-hiv-manifestations:e1/recall/1"},"syxgu4":{"a":"relationship","vg":"infect-hiv-manifestations:e1/relationship/1"},"1alnc7w":{"a":"recall","vg":"infect-hiv-manifestations:e2/recall/1"},"yip34l":{"a":"recall","vg":"infect-hiv-manifestations:e1/recall/2"},"1x785zw":{"a":"recall","vg":"infect-hiv-manifestations:e4/recall/1"},"og3h6":{"a":"recall","vg":"infect-hiv-manifestations:e4/recall/2"},"b2gfvt":{"a":"recall","vg":"infect-hiv-manifestations:e5/recall/1"},"9k8s1z":{"a":"relationship","vg":"infect-hiv-manifestations:e6/relationship/1"},"104i3i1":{"a":"recall","vg":"infect-hiv-manifestations:e6/recall/1"},"1v35rki":{"a":"recall","vg":"infect-hiv-manifestations:e7/recall/1"}},"explRev":"54c6a9519a97"};
